const Firebase = {
  getBaseUrl: function (path) {
    return FIREBASE_CONFIG.databaseURL + "/" + path + ".json?auth=" + FIREBASE_CONFIG.secret;
  },
  get: function (path) {
    const url = this.getBaseUrl(path);
    const res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    if (res.getResponseCode() === 200) return JSON.parse(res.getContentText());
    return null;
  },
  put: function (path, data) {
    const url = this.getBaseUrl(path);
    const options = { method: "put", contentType: "application/json", payload: JSON.stringify(data), muteHttpExceptions: true };
    return UrlFetchApp.fetch(url, options);
  },
  post: function (path, data) {
    const url = this.getBaseUrl(path);
    const options = { method: "post", contentType: "application/json", payload: JSON.stringify(data), muteHttpExceptions: true };
    return UrlFetchApp.fetch(url, options);
  },
  remove: function (path) {
    const url = this.getBaseUrl(path);
    const options = { method: "delete", muteHttpExceptions: true };
    return UrlFetchApp.fetch(url, options);
  }
};

// Helper untuk konversi object Firebase ke array
function getFirebaseDataAsArray(path) {
  const data = Firebase.get(path);
  if (!data) return [];
  return Object.keys(data).map(key => {
    let obj = data[key];
    obj._id = key; // menyisipkan key node jika dibutuhkan
    return obj;
  });
}

