// ==========================================
// 2. SECURITY & AUTHENTICATION
// ==========================================
function hashPassword(password) {
  var rawHash = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, password);
  var txtHash = '';
  for (var i = 0; i < rawHash.length; i++) {
    var hashVal = rawHash[i];
    if (hashVal < 0) hashVal += 256;
    if (hashVal.toString(16).length === 1) txtHash += '0';
    txtHash += hashVal.toString(16);
  }
  return txtHash;
}

function generateSessionToken(username, role) {
  var token = Utilities.getUuid();
  var cache = CacheService.getScriptCache();
  cache.put('session_' + token, JSON.stringify({ username: username, role: role, created: new Date().toISOString() }), 28800);
  cache.put('user_session_' + username, token, 28800);
  return token;
}

function validateSession(token) {
  if (!token) return { valid: false, message: 'Token tidak ditemukan' };
  var cache = CacheService.getScriptCache();
  var sessionData = cache.get('session_' + token);
  if (!sessionData) return { valid: false, message: 'Session expired. Silakan login ulang.' };
  try {
    return { valid: true, data: JSON.parse(sessionData) };
  } catch (e) {
    return { valid: false, message: 'Session tidak valid' };
  }
}

function destroySession(token) {
  var cache = CacheService.getScriptCache();
  var sessionData = cache.get('session_' + token);
  if (sessionData) {
    try {
      var parsed = JSON.parse(sessionData);
      cache.remove('user_session_' + parsed.username);
    } catch (e) { }
  }
  cache.remove('session_' + token);
  return { success: true };
}

function checkLoginRateLimit(username) {
  var cache = CacheService.getScriptCache();
  var key = 'login_fail_' + username;
  var failCount = parseInt(cache.get(key) || '0');
  if (failCount >= 5) return { allowed: false, message: 'Akun terkunci karena terlalu banyak percobaan. Coba lagi 15 menit.' };
  return { allowed: true, failCount: failCount };
}

function recordLoginFailure(username) {
  var cache = CacheService.getScriptCache();
  var key = 'login_fail_' + username;
  var failCount = parseInt(cache.get(key) || '0') + 1;
  cache.put(key, String(failCount), 900);
}

function logAction(username, action, detail) {
  try {
    const timestamp = safeDateFormat(new Date()) + " " + Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'HH:mm:ss');
    Firebase.post('AuditLog', {
      Timestamp: timestamp,
      Username: username || 'SYSTEM',
      Action: action,
      Detail: String(detail || '').substring(0, 500)
    });
  } catch (e) { }
}

function loginUser(username, password) {
  var rateCheck = checkLoginRateLimit(username);
  if (!rateCheck.allowed) return { success: false, message: rateCheck.message };

  username = String(username).trim().substring(0, 50);
  password = String(password).trim();
  if (!username || !password) return { success: false, message: 'Username dan password wajib diisi.' };

  var usersArray = getFirebaseDataAsArray('Users');
  var hashedInput = hashPassword(password);

  for (var i = 0; i < usersArray.length; i++) {
    if (String(usersArray[i].Username).trim() === username && String(usersArray[i].Password).trim() === hashedInput) {
      if (String(usersArray[i].Status) !== 'Aktif') return { success: false, message: 'Akun nonaktif.' };

      CacheService.getScriptCache().remove('login_fail_' + username);
      var role = usersArray[i].Role;
      var token = generateSessionToken(username, role);
      logAction(username, 'LOGIN', 'Login sukses');

      return {
        success: true,
        token: token,
        user: { username: username, fullname: usersArray[i].Nama, role: role }
      };
    }
  }
  recordLoginFailure(username);
  return { success: false, message: 'Username atau Password salah!' };
}

function requireRole(token, allowedRoles) {
  var session = validateSession(token);
  if (!session.valid) return { authorized: false, message: session.message, sessionExpired: true };
  if (!allowedRoles.includes(session.data.role)) return { authorized: false, message: 'Akses ditolak.' };
  return { authorized: true, username: session.data.username, role: session.data.role };
}

// ==========================================
// 3. HELPERS
// ==========================================
function safeDateFormat(value) {
  if (!value) return '';
  if (value instanceof Date) return Utilities.formatDate(value, Session.getScriptTimeZone(), 'yyyy-MM-dd');
  return String(value);
}

function sanitizeInput(value, maxLength) {
  if (!value) return '';
  return String(value).replace(/<[^>]*>/g, '').trim().substring(0, maxLength || 500);
}

