// Universal Master Data Saver
function saveMasterData(token, sheetName, payload) {
  var auth = requireRole(token, ['Admin']);
  if (!auth.authorized) return { success: false, message: auth.message, sessionExpired: auth.sessionExpired };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    if (payload.isEdit === 'true') {
      var exist = Firebase.get(sheetName + '/' + payload.id);
      if (exist) {
        var rowData = {
          [sheetName === 'MasterPoli' ? 'PoliID' : sheetName === 'MasterDokter' ? 'DokterID' : 'PelayananID']: payload.id,
          [sheetName === 'MasterPoli' ? 'NamaPoli' : sheetName === 'MasterDokter' ? 'NamaDokter' : 'NamaPelayanan']: sanitizeInput(payload.nama, 100)
        };
        if (sheetName === 'MasterDokter') rowData.PoliID = payload.poliId;

        Firebase.put(sheetName + '/' + payload.id, rowData);
        logAction(auth.username, 'UPDATE_MASTER', sheetName + ' : ' + payload.nama);
        return { success: true };
      }
      return { success: false, message: 'Data tidak ditemukan' };
    } else {
      var newId = '';
      if (sheetName === 'MasterPoli') newId = 'POL-' + new Date().getTime();
      if (sheetName === 'MasterDokter') newId = 'DOK-' + new Date().getTime();
      if (sheetName === 'MasterPelayanan') newId = 'LAY-' + new Date().getTime();

      var rowData = {
        [sheetName === 'MasterPoli' ? 'PoliID' : sheetName === 'MasterDokter' ? 'DokterID' : 'PelayananID']: newId,
        [sheetName === 'MasterPoli' ? 'NamaPoli' : sheetName === 'MasterDokter' ? 'NamaDokter' : 'NamaPelayanan']: sanitizeInput(payload.nama, 100)
      };
      if (sheetName === 'MasterDokter') rowData.PoliID = payload.poliId;

      Firebase.put(sheetName + '/' + newId, rowData);
      logAction(auth.username, 'CREATE_MASTER', sheetName + ' : ' + payload.nama);
      return { success: true };
    }
  } catch (e) {
    return { success: false, message: e.toString() };
  } finally {
    lock.releaseLock();
  }
}

function deleteMasterData(token, sheetName, id) {
  var auth = requireRole(token, ['Admin']);
  if (!auth.authorized) return { success: false, message: auth.message, sessionExpired: auth.sessionExpired };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var exist = Firebase.get(sheetName + '/' + id);
    if (exist) {
      Firebase.remove(sheetName + '/' + id);
      logAction(auth.username, 'DELETE_MASTER', sheetName + ' ID: ' + id);
      return { success: true };
    }
    return { success: false, message: 'Data tidak ditemukan.' };
  } catch (e) {
    return { success: false, message: e.toString() };
  } finally {
    lock.releaseLock();
  }
}

